<script setup lang="ts">
import type { PageDto, MatterLinkDto } from '~/types/api'
import { errorMessage } from '~/utils/format'
const props = defineProps<{ matterId: string }>()
const emit = defineEmits<{ changed: [] }>()
const open = ref(false), kind = ref('inspection'), search = ref(''), selected = ref<string>(), busy = ref(false), saving = ref(false), error = ref('')
const options = ref<{ label: string; value: string }[]>([])
const route = computed(() => kind.value === 'activity' ? 'activities' : kind.value + 's')
let timer: ReturnType<typeof setTimeout> | undefined, version = 0
async function load() { const current = ++version; busy.value = true; try { const result = await $fetch<PageDto<{ id: string; pointName?: string; description?: string; name?: string; date?: string; inspectionDate?: string }>>(`/api/${route.value}`, { query: { q: search.value, pageSize: 30 } }); if (current === version) options.value = result.items.map(item => ({ value: item.id, label: [item.name || item.pointName, item.date || item.inspectionDate, item.description].filter(Boolean).join(' · ') })) } catch (cause) { if (current === version) error.value = errorMessage(cause) } finally { if (current === version) busy.value = false } }
watch([open, kind], () => { selected.value = undefined; error.value = ''; if (open.value) void load() }); watch(search, () => { clearTimeout(timer); timer = setTimeout(load, 250) }); onBeforeUnmount(() => { ++version; clearTimeout(timer) })
async function save() { if (!selected.value || saving.value) return; saving.value = true; error.value = ''; try { const detail = await $fetch<Record<string, { matters: MatterLinkDto[] }>>(`/api/${route.value}/${selected.value}`); const record = detail[kind.value]; if (!record) throw new Error('记录读取失败'); const matterIds = [...new Set([...record.matters.map(item => item.id), props.matterId])]; await $fetch(`/api/${route.value}/${selected.value}/matters`, { method: 'PUT', body: { matterIds }, retry: 0 }); emit('changed'); open.value = false } catch (cause) { error.value = errorMessage(cause) } finally { saving.value = false } }
</script>
<template><UButton label="关联已有记录" color="neutral" variant="outline" @click="open = true" /><UModal v-model:open="open" title="关联已有记录" :dismissible="!saving" :close="!saving"><template #body><div class="space-y-3"><UAlert v-if="error" :description="error" color="error" /><UFormField label="记录类别"><USelect v-model="kind" :items="[{ label: '排查', value: 'inspection' }, { label: '整改问题', value: 'issue' }, { label: '活动', value: 'activity' }]" class="w-full" :disabled="saving" /></UFormField><UFormField label="记录"><USelectMenu v-model="selected" v-model:search-term="search" :items="options" value-key="value" ignore-filter :loading="busy" placeholder="搜索并选择记录" class="w-full" :disabled="saving" /></UFormField></div></template><template #footer><UButton label="取消" color="neutral" variant="outline" :disabled="saving" @click="open = false" /><UButton label="关联" :loading="saving" :disabled="!selected" @click="save" /></template></UModal></template>
